export function cityEssentialPhoto(cityCode: string, placeId: string): Photo | undefined {
  if (typeof cityCode !== 'string' || typeof placeId !== 'string' || !Object.hasOwn(PHOTOS, cityCode)) return undefined;
  const city = PHOTOS[cityCode];
  if (!Object.hasOwn(city, placeId)) return undefined;
  const entry = city[placeId];
  return { photo: entry.photo, photoCredit: { ...entry.photoCredit } };
}
